import type { Snippet } from "svelte";
import type { HTMLAttributes } from "svelte/elements";

export type DataAttributes = {
	[key: `data-${string}`]: string | null | undefined;
	[key: `aria-${string}`]: string | null | undefined;
};

export type PrimitiveAttributes = DataAttributes & {
	class?: string;
	id?: string;
	style?: string;
	role?: string;
	dir?: "ltr" | "rtl";
	tabindex?: number;
};

export type NativeProps<Element extends EventTarget = HTMLElement> = Omit<
	HTMLAttributes<Element>,
	"id"
> & {
	class?: string;
	id?: string;
	children?: Snippet;
};

export type Option =
	| string
	| {
			value?: string;
			label?: string;
			disabled?: boolean;
	  };

export type NormalizedOption = {
	value: string;
	label: string;
	disabled: boolean;
};

export function normalizeOption(option: Option): NormalizedOption {
	if (typeof option === "string") {
		return { value: option, label: option, disabled: false };
	}

	return {
		value: option.value ?? option.label ?? "",
		label: option.label ?? option.value ?? "",
		disabled: option.disabled ?? false,
	};
}

export function normalizeOptions(options: Option[]): NormalizedOption[] {
	return options.map(normalizeOption);
}

export function clampPercentage(value: number | null | undefined, min = 0, max = 100): number {
	if (value === null || value === undefined) return 100;
	if (!Number.isFinite(value) || !Number.isFinite(min) || !Number.isFinite(max) || max <= min) {
		return 0;
	}

	return Math.max(0, Math.min(100, ((value - min) / (max - min)) * 100));
}

import type { ClassValue } from "clsx";
import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}

import { writable } from "svelte/store";

export type ToastOptions = {
	id?: string;
	title: string;
	description?: string;
	duration?: number;
	dismissible?: boolean;
};

export type ToastData = {
	id: string;
	title: string;
	description?: string;
	duration: number;
	dismissible: boolean;
};

let toastId = 0;
const timers = new Map<string, ReturnType<typeof setTimeout>>();
const toasts = writable<ToastData[]>([]);

function close(id: string) {
	const timer = timers.get(id);
	if (timer) {
		clearTimeout(timer);
		timers.delete(id);
	}
	toasts.update((current) => current.filter((toast) => toast.id !== id));
}

function add(options: ToastOptions) {
	const id = options.id ?? `toast-${++toastId}`;
	const toast: ToastData = {
		id,
		title: options.title,
		description: options.description,
		duration: options.duration ?? 5000,
		dismissible: options.dismissible ?? true,
	};

	toasts.update((current) => [...current.filter((item) => item.id !== id), toast]);

	if (toast.duration > 0) {
		const existingTimer = timers.get(id);
		if (existingTimer) clearTimeout(existingTimer);
		timers.set(
			id,
			setTimeout(() => close(id), toast.duration)
		);
	}

	return id;
}

export const toastManager = {
	subscribe: toasts.subscribe,
	add,
	close,
};
